import * as M from './afk-model.mjs';
import * as Art from './art.mjs';
export class AfkZone {
 constructor(g){this.g=g;this.active=false;this.quantity=1;this.tab='upgrades';this.a=g.state.afk;this.a.lastTick=Date.now();this.offline=null;this.lastSave=Date.now();this.timer=null;addEventListener('pagehide',()=>{this.settle();this.a.lastTick=Date.now();g.save()});document.addEventListener('visibilitychange',()=>{this.a.lastTick=Date.now();if(document.hidden)g.save()})}
 settle(){if(!this.active||document.hidden){this.a.lastTick=Date.now();return}M.settle(this.a);const fresh=M.unlock(this.a);if(fresh.length&&this.active)this.g.toast('Succès débloqué : '+fresh.map(a=>a.name).join(' · '))}
 tick(){if(!this.active)return;this.settle();const now=Date.now();if(now-this.lastSave>=5000){this.lastSave=now;this.g.save()}if(this.active){if(!this.goldenUntil&&now>=this.nextGolden){this.goldenUntil=now+20000;this.nextGolden=now+90000+Math.random()*60000}if(this.goldenUntil&&now>=this.goldenUntil)this.goldenUntil=0;this.update()}}
 open(){if(this.active||!this.g.requireStarter())return;this.a.lastTick=Date.now();this.active=true;clearInterval(this.timer);this.timer=setInterval(()=>this.tick(),500);this.g.enterMode('afk');this.nextGolden=Date.now()+90000+Math.random()*60000;this.goldenUntil=0;this.g.modeRoot.innerHTML=`<div class="afk-app"><header class="afk-header"><div><span class="eyebrow">LE CAMP QUI NE DORT JAMAIS</span><h1>Pokéclick</h1></div><div class="afk-header-status"><span>✦ <b data-afk="production">0</b> / s</span><span>▱ <b id="afk-tickets">${this.g.state.tickets}</b> tickets</span><button data-act="afk-stats">Statistiques</button><button data-act="fullscreen" aria-label="Plein écran">⛶</button><button data-act="afk-exit">Retour au jeu ↗</button></div></header><div class="afk-mobile-nav"><button data-act="afk-jump" data-target=".afk-click-zone">◒ Poké Ball</button><button data-act="afk-jump" data-target=".afk-center">✧ Camp & bonus</button><button data-act="afk-jump" data-target=".afk-store">▣ Boutique</button></div><div class="afk-columns"><section class="afk-click-zone"><div class="afk-bank"><small>ÉNERGIE DE CAPTURE</small><strong data-afk="energy">0</strong><span><b data-afk="production">0</b> par seconde</span></div><div class="afk-ball-area"><div class="afk-aura"></div><div class="afk-orbit"></div><button class="afk-pokeball" data-act="afk-click" aria-label="Cliquer sur la Poké Ball pour produire de l’énergie"><canvas width="180" height="180" id="afk-ball"></canvas></button><span class="afk-ball-label">CLIQUE OU TOUCHE LA POKÉ BALL</span></div><div class="afk-click-info">+<b data-afk="click">1</b> énergie par clic <span>· <b data-afk="clicks">0</b> clics</span></div><div class="afk-reward-panel"><span class="eyebrow">LE COMPTOIR DU DRESSEUR</span><p>Transforme ton énergie en récompenses pour la tour.</p><button data-act="afk-ticket"><span>▱ 1 ticket universel</span><b id="afk-ticket-cost"></b></button><button data-act="afk-fragments"><span>✦ 100 fragments</span><b>1 000 énergie</b></button><small>Le prix des tickets augmente de 5 % à chaque échange.</small></div><div class="afk-offline-note">◷ Production uniquement sur Pokéclick<br>Bonus de succès : +1 % par badge obtenu</div></section><section class="afk-center"><div class="afk-news"><span>LE JOURNAL DU CAMP</span><p id="afk-news">Un Pikachu cherche un travail à temps plein. Il accepte les baies et les compliments.</p></div><div class="afk-tabs"><button data-act="afk-tab" data-tab="upgrades" class="selected">Améliorations <b id="afk-upgrade-count">0</b></button><button data-act="afk-tab" data-tab="achievements">Succès <b id="afk-badge-count">0</b></button><button data-act="afk-tab" data-tab="prestige">Renaissance <b data-afk="stars">0</b></button></div><div id="afk-content-panel"></div><div class="afk-camp-title"><h2>Ton camp Pokémon</h2><span id="afk-building-total"></span></div><div class="afk-camp" id="afk-camp"></div></section><aside class="afk-store"><div class="afk-store-title"><span class="eyebrow">TOUJOURS PLUS D’ÉNERGIE</span><h2>Boutique</h2></div><div class="afk-quantity"><span>Acheter</span>${[1,10,100].map(n=>`<button data-act="afk-quantity" data-quantity="${n}" class="${this.quantity===n?'selected':''}">×${n}</button>`).join('')}</div><div class="afk-shop-list">${M.BUILDINGS.map(b=>`<button class="afk-building" data-act="afk-buy" data-building="${b.id}"><img src="${Art.icon(b.key)}" alt="${b.name}"><span class="afk-building-name"><b>${b.name}</b><small>${b.desc}</small><em data-cost="${b.id}"></em></span><strong data-owned="${b.id}">0</strong></button>`).join('')}</div><p class="afk-shop-hint">Les prix augmentent de 15 % par installation. Achète des améliorations pour doubler leur rendement.</p></aside></div><button class="afk-golden-ball" data-act="afk-golden" aria-label="Attraper la Poké Ball dorée" hidden><span></span><small>POKÉ BALL DORÉE !</small></button></div>`;this.paintBall();this.renderCamp();this.renderTab();this.update();this.animate();if(this.offline){const x=this.offline;this.offline=null;this.g.openModal(`<div class="afk-welcome"><span class="eyebrow">LE CAMP A TRAVAILLÉ POUR TOI</span><h2>Bon retour, dresseur !</h2><span class="afk-offline-gain">+${M.format(x.gain)}</span><p>énergie produite pendant ${Math.floor(x.seconds/3600)} h ${Math.floor(x.seconds%3600/60)} min d’absence.</p><p class="muted">Au maximum huit heures de production sont comptabilisées à chaque retour.</p><button class="primary" data-act="close-modal">Retrouver mon camp</button></div>`)}}
 paintBall(){const c=this.g.modeRoot.querySelector('#afk-ball'),x=c.getContext('2d');x.imageSmoothingEnabled=false;x.clearRect(0,0,180,180);for(let py=0;py<180;py++)for(let px=0;px<180;px++){const dx=px-90,dy=py-90,r=Math.hypot(dx,dy);if(r>73)continue;let color;const center=Math.hypot(dx,dy-1),shade=(dx+dy)*.003;const highlight=(px-63)**2/900+(py-48)**2/400<1;if(r>68)color='#151b29';else if(center<22)color=center>17?'#141d2b':center>13?'#c6cfda':center>10?'#172232':highlight?'#ffffff':'#f0f1e9';else if(Math.abs(dy)<7)color='#151d2a';else if(dy<0)color=highlight?'#ffaaa0':shade<-.08?'#f7635a':shade>.13?'#a63147':'#dd4352';else color=shade>.18?'#8c9eaf':shade>.05?'#c1cbd2':'#f3ece0';x.fillStyle=color;x.fillRect(px,py,1,1)}x.fillStyle='#ffe4d870';x.fillRect(49,41,8,3);x.fillRect(45,45,4,7)}
 animate(){cancelAnimationFrame(this.raf);const loop=t=>{if(!this.active)return;this.raf=requestAnimationFrame(loop);if(document.hidden||t-(this.lastFrame||0)<65)return;this.lastFrame=t;const time=this.g.state.settings.reducedMotion?0:t/1000;for(const c of this.g.modeRoot.querySelectorAll('canvas[data-afk-mon]')){const rect=c.getBoundingClientRect();if(rect.bottom<80||rect.top>innerHeight)continue;const ctx=c.getContext('2d');ctx.clearRect(0,0,c.width,c.height);const copies=+c.dataset.copies||1;for(let i=0;i<copies;i++)Art.drawMon(ctx,c.dataset.afkMon,c.dataset.copies?30+i*43:c.width/2,c.height*.53,c.dataset.copies?55:115,'Idle',0,time+i*.2)}};this.raf=requestAnimationFrame(loop)}
 renderCamp(){if(!this.active)return;const owned=M.BUILDINGS.filter(b=>this.a.buildings[b.id]>0);this.g.modeRoot.querySelector('#afk-camp').innerHTML=owned.map((b,i)=>`<article class="afk-camp-row afk-biome-${i%4}"><div><b>${b.name}</b><span>${this.a.buildings[b.id]} en activité</span></div><canvas width="560" height="80" data-afk-mon="${b.key}" data-copies="${Math.min(12,this.a.buildings[b.id])}"></canvas></article>`).join('')||`<div class="afk-empty-camp"><canvas width="200" height="150" data-afk-mon="${this.g.state.starter||4}"></canvas><h3>Tout commence par un lancer.</h3><p>Clique sur la Poké Ball, puis recrute ton premier Pikachu assistant pour 15 énergies.</p></div>`;Art.preload(owned.map(b=>b.key))}
 renderTab(){if(!this.active)return;const root=this.g.modeRoot;root.querySelectorAll('.afk-tabs button').forEach(b=>b.classList.toggle('selected',b.dataset.tab===this.tab));const panel=root.querySelector('#afk-content-panel');if(this.tab==='upgrades'){const available=M.UPGRADES.filter(u=>!this.a.upgrades.includes(u.id)&&u.need(this.a));panel.innerHTML=`<div class="afk-upgrades">${available.map(u=>`<button data-act="afk-upgrade" data-upgrade="${u.id}" data-price="${u.cost}"><span>✧</span><b>${u.name}</b><small>${u.desc}</small><strong>${M.format(u.cost)} énergie</strong></button>`).join('')||'<p class="afk-panel-empty">Continue à cliquer et à recruter : de nouvelles améliorations se débloqueront ici.</p>'}</div><p class="afk-tab-note">${this.a.upgrades.length} améliorations achetées · De nouveaux paliers à 1, 10 et 25 installations.</p>`}else if(this.tab==='achievements')panel.innerHTML=`<div class="afk-achievements">${M.ACHIEVEMENTS.map(a=>`<div class="${this.a.achievements.includes(a.id)?'unlocked':''}"><span>${this.a.achievements.includes(a.id)?'✦':'◇'}</span><b>${a.name}</b><small>${a.desc}</small></div>`).join('')}</div><p class="afk-tab-note">Chaque succès accorde +1 % de production automatique, définitivement.</p>`;else panel.innerHTML=`<div class="afk-prestige"><span>♜</span><h3>Renaître des cendres</h3><p>Repars avec un camp vide pour gagner des étoiles de prestige. Chaque étoile apporte +5 % aux clics et à la production.</p><strong>${M.prestigeGain(this.a)} étoile${M.prestigeGain(this.a)>1?'s':''} à gagner</strong><small>Première étoile à 1 million d’énergies produites au total. Tes Pokémon, tickets, objets et succès sont conservés.</small><button data-act="afk-prestige" ${M.prestigeGain(this.a)<1?'disabled':''}>Préparer la renaissance</button></div>`;this.panelSignature=this.signature()}
 signature(){return this.a.upgrades.length+':'+this.a.achievements.length+':'+M.UPGRADES.filter(u=>!this.a.upgrades.includes(u.id)&&u.need(this.a)).map(u=>u.id).join(',')+':'+M.prestigeGain(this.a)}
 update(){if(!this.active)return;const r=this.g.modeRoot,a=this.a,values={energy:M.format(a.energy),production:M.format(M.production(a)),click:M.format(M.clickPower(a)),clicks:M.format(a.clicks),stars:M.format(a.stars)};for(const el of r.querySelectorAll('[data-afk]'))el.textContent=values[el.dataset.afk];r.querySelector('#afk-tickets').textContent=this.g.state.tickets;r.querySelector('#afk-ticket-cost').textContent=M.format(M.ticketCost(a))+' énergie';r.querySelector('[data-act="afk-ticket"]').disabled=a.energy<M.ticketCost(a);r.querySelector('[data-act="afk-fragments"]').disabled=a.energy<1000;for(const b of M.BUILDINGS){const cost=M.buildingCost(a,b.id,this.quantity),button=r.querySelector('[data-building="'+b.id+'"]');button.disabled=!Number.isFinite(cost)||a.energy<cost;button.querySelector('[data-cost]').textContent=M.format(cost)+' énergie · '+M.format(b.rate)+' / s de base';button.querySelector('[data-owned]').textContent=a.buildings[b.id]}r.querySelector('#afk-upgrade-count').textContent=a.upgrades.length;r.querySelector('#afk-badge-count').textContent=a.achievements.length+'/'+M.ACHIEVEMENTS.length;r.querySelector('#afk-building-total').textContent=Object.values(a.buildings).reduce((s,n)=>s+n,0)+' installations';r.querySelector('.afk-golden-ball').hidden=!this.goldenUntil;if(this.signature()!==this.panelSignature)this.renderTab();for(const b of r.querySelectorAll('[data-act="afk-upgrade"]'))b.disabled=a.energy<Number(b.dataset.price);if(Date.now()-(this.newsAt||0)>25000){this.newsAt=Date.now();const news=['Un Pikachu cherche un travail à temps plein. Il accepte les baies et les compliments.','Les Leveinard du camp réclament une machine à café. Le comité des baies étudie la demande.','Un Racaillou a découvert un caillou. Le camp célèbre cette avancée historique.','Le professeur confirme : regarder la Poké Ball ne la fait pas cliquer toute seule. Les Pikachu, si.'];r.querySelector('#afk-news').textContent=news[Math.floor(Math.random()*news.length)]}}
 click(){if(!this.active||this.g.modal.open)return;this.settle();const amount=M.gain(this.a,M.clickPower(this.a));this.a.clicks++;M.unlock(this.a);this.update();this.deferSave();const area=this.g.modeRoot.querySelector('.afk-ball-area'),pop=document.createElement('span');pop.className='afk-click-pop';pop.textContent='+'+M.format(amount);pop.style.left=(43+Math.random()*14)+'%';pop.style.top=(33+Math.random()*15)+'%';area.append(pop);setTimeout(()=>pop.remove(),850);const b=area.querySelector('.afk-pokeball');b.getAnimations().forEach(a=>a.cancel());b.animate([{transform:'scale(1)'},{transform:'scale(.93) rotate(-3deg)'},{transform:'scale(1.025)'},{transform:'scale(1)'}],{duration:this.g.state.settings.reducedMotion?1:170});this.g.audio.tone(280+Math.random()*90,.035,.009)}
 deferSave(){if(this.saveTimeout)return;this.saveTimeout=setTimeout(()=>{this.saveTimeout=null;this.g.save()},1000)}
 buy(id){this.settle();if(M.buyBuilding(this.a,id,this.quantity)){this.g.save();this.renderCamp();this.update();this.g.audio.tone(440,.08)}else this.g.toast('Il te manque de l’énergie pour cet achat.')}
 upgrade(id){this.settle();if(M.buyUpgrade(this.a,id)){this.g.save();this.renderTab();this.update();this.g.audio.chime('rare')}}
 exchange(kind){this.settle();const cost=kind==='ticket'?M.ticketCost(this.a):1000;if(this.a.energy<cost)return;this.a.energy-=cost;if(kind==='ticket'){this.a.exchanged++;this.g.state.tickets++;this.g.toast('+1 ticket universel !')}else{this.g.state.coins+=100;this.g.toast('+100 fragments !')}this.g.save();this.update()}
 golden(){if(!this.active||!this.goldenUntil||Date.now()>=this.goldenUntil)return;this.settle();this.goldenUntil=0;this.a.golden++;const amount=M.gain(this.a,Math.max(50,M.production(this.a)*60+M.clickPower(this.a)*100));M.unlock(this.a);this.g.save();this.update();this.g.audio.chime('legendary');this.g.toast('Poké Ball dorée ! +'+M.format(amount)+' énergie')}
 preparePrestige(){if(!M.prestigeGain(this.a))return;this.g.openModal(`<div class="afk-welcome"><span class="eyebrow">UNE NOUVELLE ASCENSION</span><h2>Renaissance du camp</h2><p>Tu gagneras <b>${M.prestigeGain(this.a)} étoile(s)</b>, soit +5 % par étoile sur les clics et la production.</p><p>Ton énergie restante, tes installations et les améliorations AFK seront remises à zéro. Tes succès et toute ta progression dans le reste du jeu seront conservés.</p><button class="primary" data-act="afk-confirm-prestige">Renaître des cendres</button><button data-act="close-modal">Continuer mon camp</button></div>`)}
 confirmPrestige(){this.settle();const stars=M.prestige(this.a);this.g.closeModal();if(stars){this.g.save();this.renderCamp();this.renderTab();this.update();this.g.toast('Renaissance ! +'+stars+' étoile(s) de prestige.')}}
 stats(){this.settle();this.g.openModal(`<div class="afk-welcome"><span class="eyebrow">LE BILAN DU CAMP</span><h2>Statistiques AFK</h2><div class="afk-stats-grid">${[['Énergie disponible',M.format(this.a.energy)],['Produite depuis le début',M.format(this.a.total)],['Production / seconde',M.format(M.production(this.a))],['Énergie par clic',M.format(M.clickPower(this.a))],['Clics effectués',M.format(this.a.clicks)],['Poké Balls dorées',this.a.golden],['Tickets échangés',this.a.exchanged],['Étoiles de prestige',this.a.stars]].map(([k,v])=>`<div><span>${k}</span><b>${v}</b></div>`).join('')}</div><button class="primary" data-act="close-modal">Retour au camp</button></div>`)}
 stop(){if(!this.active)return;this.settle();this.g.save();this.active=false;clearInterval(this.timer);this.timer=null;cancelAnimationFrame(this.raf);this.goldenUntil=0;this.g.leaveMode();this.g.route('home')}
}
